using FolderVerse;using Microsoft.Xna.Framework;
if(args.Contains("--ui")){using var game=new CrossfirePreview();game.Run();return;}
int count=0;void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;}
BattleState Board(bool learned=false){var b=new BattleState(42){Kind=BattleKind.Edge,EquipmentMode=RobotEquipmentMode.Materials};b.Armies.Add(new(){Owner=0,Side=0});b.Armies.Add(new(){Owner=1,Side=2});b.CrossfireEnabled[0]=true;
b.Units.Add(new(){Id=1,Owner=0,Role=BattleRole.Captain,Position=new(2,2),Robot=new Robot(1,0,RobotParts.Complete,RobotRole.Captain)});
b.Units.Add(new(){Id=2,Owner=0,Position=new(2,6),Rifles=2,Daggers=0,Robot=new Robot(2,0,RobotParts.Complete)});
b.Units.Add(new(){Id=3,Owner=0,Position=new(6,2),Rifles=2,Daggers=0,Robot=new Robot(3,0,RobotParts.Complete)});
b.Units.Add(new(){Id=4,Owner=0,Position=new(5,5),Facing=BattleFacing.North,Rifles=0,Daggers=1,Robot=new Robot(4,0,RobotParts.Complete)});
b.Units.Add(new(){Id=5,Owner=1,Position=new(6,6),Facing=BattleFacing.North,Rifles=0,Daggers=0,Shields=1});if(learned)b.Lessons[0]=BattleLesson.CrossfireSafety;return b;}
CrossfirePlan[] Plan(BattleState b){var units=b.Units.Where(u=>u.Active).ToArray();var a=units.ToDictionary(u=>u.Id,u=>new BattleAction(Point.Zero,u.Facing));return BattleTactics.PlanCrossfire(b,units,a);}
var b=Board();Check(Plan(b).Length==1,"Captain and two perpendicular shooters activate");b.CrossfireEnabled[0]=false;Check(Plan(b).Length==0,"No tactic means no coordination");b.CrossfireEnabled[0]=true;b.Units[0].Retreating=true;Check(Plan(b).Length==0,"Retreating captain cannot signal");b.Units[0].Retreating=false;b.Walls.Add(new(3,3));Check(Plan(b).Length==0,"Captain vision blocked by cover");b.Walls.Clear();b.Walls.Add(new(4,6));Check(Plan(b).Length==0,"Shooter path blocked");b.Walls.Clear();b.Units[2].Rifles=0;Check(Plan(b).Length==0,"Two loaded rifles required");
var raw=Board();BattleTurnResolver.Advance(raw);Check(raw.Attacks.Any(a=>a.Attacker==2&&a.Target==4),"Unlearned crossfire can hit friend entering ray");Check(raw.Attacks.Any(a=>a.Attacker==3)&&raw.Events.Any(e=>e.Detail==BattleTactics.CrossfireSignal&&e.Unit==1),"Other shooter fires in same phase and captain signals");Check(raw.Units.Single(u=>u.Id==2).Rifles==1,"Actual firing consumes ammunition");Check(raw.Units.Any(u=>(u.WitnessedLessons&BattleLesson.CrossfireSafety)!=0),"Actual friendly hit witnesses lesson18");var book=new BattleLessons();foreach(var u in raw.Units)book.BringHome(u);Check(book.Research().Any(a=>a.Lesson==BattleLesson.CrossfireSafety),"Surviving witnesses bring lesson home and research");
var safe=Board(true);BattleTurnResolver.Advance(safe);Check(!safe.Attacks.Any(a=>a.Attacker==2)&&safe.Units.Single(u=>u.Id==2).Rifles==2,"Learned shooter cancels friendly shot without ammo cost");Check(safe.Attacks.Any(a=>a.Attacker==3)&&!safe.Units.Single(u=>u.Id==4).Fallen,"Safe perpendicular shooter still fires and friend survives");Check(!safe.Units.Any(u=>(u.WitnessedLessons&BattleLesson.CrossfireSafety)!=0),"Avoided shot is not a new friendly-fire incident");var restored=AutoSaveStore.Restore<BattleState>(AutoSaveStore.Capture(safe));Check(restored.CrossfireEnabled[0]&&restored.Lessons[0]==BattleLesson.CrossfireSafety,"Availability and lesson survive save");var old=AutoSaveStore.Capture(safe);foreach(var e in old.Objects)e.Fields?.Remove("CrossfireEnabled");Check(!AutoSaveStore.Restore<BattleState>(old).CrossfireEnabled.Any(x=>x),"Old saves default OFF");Check(Enumerable.Range(0,60).Count(BattleTactics.UsesCrossfire)==30,"Thirty characters have crossfire");Console.WriteLine($"PASS {count} crossfire checks");
var distant=Board();distant.Units[0].Position=new(11,11);distant.Units[1].Position=new(0,6);distant.Units[2].Position=new(6,0);Check(Plan(distant).Length==1,"Radio command and normal rifle have no extra distance ceiling");var normal=Board();normal.CrossfireEnabled[0]=false;BattleTurnResolver.Advance(normal);Check(!normal.Events.Any(e=>e.Detail==BattleTactics.Crossfire)&&!normal.Units.Any(u=>(u.WitnessedLessons&BattleLesson.CrossfireSafety)!=0),"Ordinary attacks do not acquire crossfire lesson");var explicitOrders=Board();BattleTurnResolver.Advance(explicitOrders,explicitOrders.Units.ToDictionary(u=>u.Id,u=>new BattleAction(Point.Zero,u.Facing)));Check(!explicitOrders.Events.Any(e=>e.Detail==BattleTactics.Crossfire),"Explicit orders are not replaced by tactics");var deadWitness=new BattleUnit{Id=99,Owner=0,Robot=new Robot(99,0,RobotParts.Complete),Fallen=true,WitnessedLessons=BattleLesson.CrossfireSafety};var lost=new BattleLessons();lost.BringHome(deadWitness);Check(!lost.Pending.Any(),"Fallen witness cannot research");Console.WriteLine("PASS 4 additional crossfire checks");
